  void EnsureEditable(){if(scanCancellation!=null||warpCancellation!=null)throw new InvalidOperationException("Дождитесь завершения или отмените текущую проверку.");}
  Choice[] RouteOutputs(){var choices=new List<Choice>{new Choice{Key="direct",Label="Напрямую"},new Choice{Key="proxy",Label="VPN / прокси"},new Choice{Key="block",Label="Блокировать"},new Choice{Key="tgws",Label="Telegram WS"},new Choice{Key="byetube",Label="ByeTube"}};choices.AddRange(session.State.ZapretProfiles.Select(p=>new Choice{Key="zapret:"+p.Id,Label="Zapret → "+p.Name}));choices.AddRange(WarpOutputs.Profiles(session.State).Select(n=>new Choice{Key=WarpOutputs.Tag(n),Label="WARP → "+n.Name}));return choices.ToArray();}
  async Task RouteChange(Action action,bool refresh=true){var serializer=new JavaScriptSerializer{MaxJsonLength=Int32.MaxValue};var before=session.State.Lists.ToDictionary(r=>r.Id,r=>serializer.Serialize(r));await session.ChangeConfiguration(()=>{action();foreach(var route in session.State.Lists.Where(r=>r.Enabled&&(!before.ContainsKey(r.Id)||before[r.Id]!=serializer.Serialize(r)))){if(String.IsNullOrEmpty(route.Target))throw new InvalidOperationException("Выберите выход для «"+route.Name+"» перед включением.");ZapretRoutes.Validate(route,session.State.ZapretProfiles.ToArray());}});if(refresh)RefreshAfterOperation("Маршрутизация");}
  static TextBlock CellText(string text){return new TextBlock{Text=text,TextWrapping=TextWrapping.NoWrap,TextTrimming=TextTrimming.CharacterEllipsis,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(4,0,4,0),Foreground=Brush("#DCE6F8")};}
  static int EntryCount(string text){try{return RouteCompiler.Parse(text??"").Values.Sum(v=>v.Count);}catch(FormatException){return 0;}}
  void RestoreRouteTable(DataGrid table){var selected=table.SelectedItems.Cast<RouteList>().Select(r=>r.Id).ToArray();var scroll=FindScrollViewer(table);double vertical=scroll==null?0:scroll.VerticalOffset,horizontal=scroll==null?0:scroll.HorizontalOffset;table.ItemsSource=session.State.Lists;foreach(var row in session.State.Lists.Where(r=>selected.Contains(r.Id)))table.SelectedItems.Add(row);Dispatcher.BeginInvoke(new Action(()=>{if(!table.IsLoaded)return;var currentScroll=FindScrollViewer(table);if(currentScroll!=null){currentScroll.ScrollToVerticalOffset(vertical);currentScroll.ScrollToHorizontalOffset(horizontal);}}),System.Windows.Threading.DispatcherPriority.Loaded);}
  async Task RouteTransportChange(DataGrid table,CheckBox check,string id,bool tcp){
   bool desired=check.IsChecked==true;
   try{await Run(async()=>{
    // Validate a copy first: rejecting an unsafe rule must not replace the
    // entire state/page and destroy column sizing, selection or focus.
    var currentRoute=session.State.Lists.Single(r=>r.Id==id);var json=new JavaScriptSerializer{MaxJsonLength=Int32.MaxValue};var proposed=json.Deserialize<RouteList>(json.Serialize(currentRoute));if(tcp)proposed.GameFilterTcp=desired;else proposed.GameFilterUdp=desired;if(proposed.Enabled)ZapretRoutes.Validate(proposed,session.State.ZapretProfiles);
    await RouteChange(()=>{var route=session.State.Lists.Single(r=>r.Id==id);if(tcp)route.GameFilterTcp=desired;else route.GameFilterUdp=desired;},false);
    status.Text=(tcp?"TCP":"UDP")+" · изменение сохранено.";
   },()=>RestoreRouteTable(table));}
   finally{var actual=session.State.Lists.FirstOrDefault(r=>r.Id==id);if(actual!=null)check.IsChecked=tcp?actual.GameTcpEnabled:actual.GameUdpEnabled;}
  }
